Index: packages/KNIRVAGENT/pkg/inner/catalog.go
===================================================================
--- packages/KNIRVAGENT/pkg/inner/catalog.go	
+++ packages/KNIRVAGENT/pkg/inner/catalog.go	
@@ -0,0 +1,58 @@
+package inner
+
+import (
+	"os"
+	"os/exec"
+)
+
+type Tool struct {
+	Name        string
+	Binary      string
+	DefaultArgs []string
+	InstallCmd  []string
+}
+
+func (t *Tool) IsInstalled() bool {
+	_, err := exec.LookPath(t.Binary)
+	return err == nil
+}
+
+func (t *Tool) Install(workdir string) error {
+	cmd := exec.Command(t.InstallCmd[0], t.InstallCmd[1:]...)
+	cmd.Dir = workdir
+	cmd.Stdout, cmd.Stderr = os.Stdout, os.Stderr
+	return cmd.Run()
+}
+
+func (t *Tool) BuildCmd(workdir string, extra []string) *exec.Cmd {
+	cmd := exec.Command(t.Binary, t.DefaultArgs...)
+	cmd.Dir = workdir
+	cmd.Env = append(os.Environ(), extra...)
+	return cmd
+}
+
+type ToolCatalog struct {
+	tools map[string]*Tool
+}
+
+func (c *ToolCatalog) Lookup(name string) (*Tool, bool) {
+	t, ok := c.tools[name]
+	return t, ok
+}
+
+func (c *ToolCatalog) All() []Tool {
+	out := make([]Tool, 0, len(c.tools))
+	for _, t := range c.tools {
+		out = append(out, *t)
+	}
+	return out
+}
+
+func DefaultCatalog() *ToolCatalog {
+	return &ToolCatalog{tools: map[string]*Tool{
+		"claude":     {Name: "claude", Binary: "claude", DefaultArgs: []string{"--no-auto-update"}, InstallCmd: []string{"npm", "install", "-g", "@anthropic-ai/claude-code"}},
+		"aider":      {Name: "aider", Binary: "aider", InstallCmd: []string{"pip", "install", "aider-chat"}},
+		"codex":      {Name: "codex", Binary: "codex", InstallCmd: []string{"npm", "install", "-g", "@openai/codex"}},
+		"gh-copilot": {Name: "gh-copilot", Binary: "gh", DefaultArgs: []string{"copilot"}, InstallCmd: []string{"gh", "extension", "install", "github/gh-copilot"}},
+	}}
+}

Index: packages/KNIRVAGENT/pkg/inner/manager.go
===================================================================
--- packages/KNIRVAGENT/pkg/inner/manager.go	
+++ packages/KNIRVAGENT/pkg/inner/manager.go	
@@ -0,0 +1,135 @@
+package inner
+
+import (
+	"fmt"
+	"os"
+	"sync"
+	"time"
+
+	"github.com/creack/pty"
+	"github.com/google/uuid"
+)
+
+type InnerAgentManager struct {
+	mu           sync.RWMutex
+	sessions     map[string]*InnerAgentSession
+	catalog      *ToolCatalog
+	workspaceDir string
+	dveID        string
+	logDir       string
+}
+
+func NewInnerAgentManager(dveID, workspaceDir string) *InnerAgentManager {
+	logDir := workspaceDir + "/.supervisor-logs"
+	os.MkdirAll(logDir, 0755)
+	return &InnerAgentManager{
+		sessions:     make(map[string]*InnerAgentSession),
+		catalog:      DefaultCatalog(),
+		workspaceDir: workspaceDir,
+		dveID:        dveID,
+		logDir:       logDir,
+	}
+}
+
+func (m *InnerAgentManager) Spawn(toolName string, extraEnv []string) (*InnerAgentSession, error) {
+	tool, ok := m.catalog.Lookup(toolName)
+	if !ok {
+		return nil, fmt.Errorf("unknown tool: %s", toolName)
+	}
+	if !tool.IsInstalled() {
+		return nil, fmt.Errorf("tool %s not installed; call Install first", toolName)
+	}
+
+	sessionID := uuid.NewString()
+	logFile, err := os.Create(fmt.Sprintf("%s/%s.log", m.logDir, sessionID))
+	if err != nil {
+		return nil, err
+	}
+
+	cmd := tool.BuildCmd(m.workspaceDir, extraEnv)
+	DefaultSpawnHooks(cmd, m.dveID, sessionID)
+
+	ptmx, err := pty.Start(cmd)
+	if err != nil {
+		logFile.Close()
+		return nil, fmt.Errorf("pty.Start: %w", err)
+	}
+
+	sess := &InnerAgentSession{
+		ID:            sessionID,
+		ToolName:      toolName,
+		Cmd:           cmd,
+		PTY:           ptmx,
+		Status:        StatusRunning,
+		StartedAt:     time.Now(),
+		WorkspaceDir:  m.workspaceDir,
+		DVEID:         m.dveID,
+		supervisorLog: logFile,
+		done:          make(chan struct{}),
+	}
+
+	m.mu.Lock()
+	m.sessions[sessionID] = sess
+	m.mu.Unlock()
+
+	go sess.PumpOutput()
+	return sess, nil
+}
+
+func (m *InnerAgentManager) SendInput(sessionID string, data []byte) error {
+	sess := m.get(sessionID)
+	if sess == nil {
+		return fmt.Errorf("session %s not found", sessionID)
+	}
+	_, err := sess.PTY.Write(data)
+	return err
+}
+
+func (m *InnerAgentManager) Install(toolName string) error {
+	tool, ok := m.catalog.Lookup(toolName)
+	if !ok {
+		return fmt.Errorf("unknown tool: %s", toolName)
+	}
+	return tool.Install(m.workspaceDir)
+}
+
+func (m *InnerAgentManager) Terminate(sessionID string) error {
+	sess := m.get(sessionID)
+	if sess == nil {
+		return nil
+	}
+	if sess.Cmd != nil && sess.Cmd.Process != nil {
+		sess.Cmd.Process.Kill()
+	}
+	sess.PTY.Close()
+	m.mu.Lock()
+	delete(m.sessions, sessionID)
+	m.mu.Unlock()
+	return nil
+}
+
+func (m *InnerAgentManager) GetSession(id string) (*InnerAgentSession, error) {
+	sess := m.get(id)
+	if sess == nil {
+		return nil, fmt.Errorf("session %s not found", id)
+	}
+	return sess, nil
+}
+
+func (m *InnerAgentManager) ListSessions() []*InnerAgentSession {
+	m.mu.RLock()
+	defer m.mu.RUnlock()
+	out := make([]*InnerAgentSession, 0, len(m.sessions))
+	for _, s := range m.sessions {
+		out = append(out, s)
+	}
+	return out
+}
+
+func (m *InnerAgentManager) ListTools() []Tool { return m.catalog.All() }
+
+func (m *InnerAgentManager) get(id string) *InnerAgentSession {
+	m.mu.RLock()
+	defer m.mu.RUnlock()
+	return m.sessions[id]
+}

Index: packages/KNIRVAGENT/pkg/inner/session.go
===================================================================
--- packages/KNIRVAGENT/pkg/inner/session.go	
+++ packages/KNIRVAGENT/pkg/inner/session.go	
@@ -0,0 +1,85 @@
+package inner
+
+import (
+	"io"
+	"os"
+	"os/exec"
+	"sync"
+	"time"
+)
+
+type SessionStatus string
+
+const (
+	StatusRunning SessionStatus = "running"
+	StatusExited  SessionStatus = "exited"
+)
+
+type InnerAgentSession struct {
+	ID           string
+	ToolName     string
+	Cmd          *exec.Cmd
+	PTY          *os.File
+	Status       SessionStatus
+	StartedAt    time.Time
+	WorkspaceDir string
+	DVEID        string
+
+	supervisorLog io.Writer
+
+	mu          sync.RWMutex
+	subscribers []chan []byte
+	done        chan struct{}
+}
+
+func (s *InnerAgentSession) Subscribe() chan []byte {
+	ch := make(chan []byte, 256)
+	s.mu.Lock()
+	s.subscribers = append(s.subscribers, ch)
+	s.mu.Unlock()
+	return ch
+}
+
+func (s *InnerAgentSession) Unsubscribe(ch chan []byte) {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	for i, sub := range s.subscribers {
+		if sub == ch {
+			s.subscribers = append(s.subscribers[:i], s.subscribers[i+1:]...)
+			return
+		}
+	}
+}
+
+func (s *InnerAgentSession) broadcast(chunk []byte) {
+	s.supervisorLog.Write(chunk)
+	s.mu.RLock()
+	defer s.mu.RUnlock()
+	for _, ch := range s.subscribers {
+		select {
+		case ch <- append([]byte(nil), chunk...):
+		default:
+		}
+	}
+}
+
+func (s *InnerAgentSession) PumpOutput() {
+	buf := make([]byte, 4096)
+	for {
+		n, err := s.PTY.Read(buf)
+		if n > 0 {
+			s.broadcast(buf[:n])
+		}
+		if err != nil {
+			break
+		}
+	}
+	s.mu.Lock()
+	s.Status = StatusExited
+	for _, ch := range s.subscribers {
+		close(ch)
+	}
+	s.subscribers = nil
+	s.mu.Unlock()
+	close(s.done)
+}

Index: packages/KNIRVAGENT/pkg/server/inner_routes.go
===================================================================
--- packages/KNIRVAGENT/pkg/server/inner_routes.go	
+++ packages/KNIRVAGENT/pkg/server/inner_routes.go	
@@ -0,0 +1,185 @@
+package server
+
+import (
+	"encoding/json"
+	"io"
+	"net/http"
+	"os"
+	"strings"
+
+	"github.com/knirvcorp/knirvagent/pkg/inner"
+)
+
+func RegisterInnerRoutes(mux *http.ServeMux, mgr *inner.InnerAgentManager) {
+	mux.HandleFunc("/api/inner/spawn", handleSpawn(mgr))
+	mux.HandleFunc("/api/inner/install", handleInstall(mgr))
+	mux.HandleFunc("/api/inner/sessions", handleListSessions(mgr))
+	mux.HandleFunc("/api/inner/tools", handleListTools(mgr))
+	mux.HandleFunc("/api/inner/", handleSessionRouter(mgr))
+}
+
+func handleSpawn(mgr *inner.InnerAgentManager) http.HandlerFunc {
+	return func(w http.ResponseWriter, r *http.Request) {
+		if r.Method != "POST" {
+			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
+			return
+		}
+		var req struct {
+			Tool    string   `json:"tool"`
+			ExtraEnv []string `json:"extra_env,omitempty"`
+		}
+		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
+			http.Error(w, "invalid request: "+err.Error(), http.StatusBadRequest)
+			return
+		}
+		if req.Tool == "" {
+			http.Error(w, "tool is required", http.StatusBadRequest)
+			return
+		}
+		sess, err := mgr.Spawn(req.Tool, req.ExtraEnv)
+		if err != nil {
+			http.Error(w, err.Error(), http.StatusInternalServerError)
+			return
+		}
+		w.Header().Set("Content-Type", "application/json")
+		json.NewEncoder(w).Encode(map[string]interface{}{
+			"id":             sess.ID,
+			"tool":           sess.ToolName,
+			"status":         sess.Status,
+			"started_at":     sess.StartedAt,
+			"workspace_dir":  sess.WorkspaceDir,
+		})
+	}
+}
+
+func handleInstall(mgr *inner.InnerAgentManager) http.HandlerFunc {
+	return func(w http.ResponseWriter, r *http.Request) {
+		if r.Method != "POST" {
+			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
+			return
+		}
+		var req struct {
+			Tool string `json:"tool"`
+		}
+		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
+			http.Error(w, "invalid request: "+err.Error(), http.StatusBadRequest)
+			return
+		}
+		if err := mgr.Install(req.Tool); err != nil {
+			http.Error(w, err.Error(), http.StatusInternalServerError)
+			return
+		}
+		w.WriteHeader(http.StatusNoContent)
+	}
+}
+
+func handleListSessions(mgr *inner.InnerAgentManager) http.HandlerFunc {
+	return func(w http.ResponseWriter, r *http.Request) {
+		if r.Method != "GET" {
+			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
+			return
+		}
+		sessions := mgr.ListSessions()
+		result := make([]map[string]interface{}, 0, len(sessions))
+		for _, s := range sessions {
+			result = append(result, map[string]interface{}{
+				"id":            s.ID,
+				"tool":          s.ToolName,
+				"status":        s.Status,
+				"started_at":    s.StartedAt,
+				"workspace_dir": s.WorkspaceDir,
+			})
+		}
+		w.Header().Set("Content-Type", "application/json")
+		json.NewEncoder(w).Encode(result)
+	}
+}
+
+func handleListTools(mgr *inner.InnerAgentManager) http.HandlerFunc {
+	return func(w http.ResponseWriter, r *http.Request) {
+		if r.Method != "GET" {
+			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
+			return
+		}
+		w.Header().Set("Content-Type", "application/json")
+		json.NewEncoder(w).Encode(mgr.ListTools())
+	}
+}
+
+func handleSessionRouter(mgr *inner.InnerAgentManager) http.HandlerFunc {
+	return func(w http.ResponseWriter, r *http.Request) {
+		rest := strings.TrimPrefix(r.URL.Path, "/api/inner/")
+		parts := strings.SplitN(rest, "/", 2)
+		sessionID := parts[0]
+		action := ""
+		if len(parts) == 2 {
+			action = parts[1]
+		}
+
+		switch {
+		case r.Method == "DELETE" && action == "":
+			mgr.Terminate(sessionID)
+			w.WriteHeader(http.StatusNoContent)
+		case action == "input" && r.Method == "POST":
+			data, _ := io.ReadAll(io.LimitReader(r.Body, 4096))
+			mgr.SendInput(sessionID, data)
+			w.WriteHeader(http.StatusNoContent)
+		case action == "stream" && r.Method == "GET":
+			handleStream(mgr, sessionID, w, r)
+		case action == "log" && r.Method == "GET":
+			handleGetLog(mgr, sessionID, w)
+		default:
+			http.NotFound(w, r)
+		}
+	}
+}
+
+func handleStream(mgr *inner.InnerAgentManager, sessionID string, w http.ResponseWriter, r *http.Request) {
+	sess, err := mgr.GetSession(sessionID)
+	if err != nil {
+		http.Error(w, err.Error(), http.StatusNotFound)
+		return
+	}
+
+	w.Header().Set("Content-Type", "application/octet-stream")
+	w.Header().Set("Transfer-Encoding", "chunked")
+	w.Header().Set("X-Accel-Buffering", "no")
+	w.WriteHeader(http.StatusOK)
+
+	flusher, _ := w.(http.Flusher)
+	ch := sess.Subscribe()
+	defer sess.Unsubscribe(ch)
+
+	for {
+		select {
+		case chunk, ok := <-ch:
+			if !ok {
+				return
+			}
+			if _, err := w.Write(chunk); err != nil {
+				return
+			}
+			if flusher != nil {
+				flusher.Flush()
+			}
+		case <-r.Context().Done():
+			return
+		}
+	}
+}
+
+func handleGetLog(mgr *inner.InnerAgentManager, sessionID string, w http.ResponseWriter) {
+	sess, err := mgr.GetSession(sessionID)
+	if err != nil {
+		http.Error(w, err.Error(), http.StatusNotFound)
+		return
+	}
+	logPath := sess.WorkspaceDir + "/.supervisor-logs/" + sessionID + ".log"
+	data, err := os.ReadFile(logPath)
+	if err != nil {
+		http.Error(w, "log not found", http.StatusNotFound)
+		return
+	}
+	w.Header().Set("Content-Type", "text/plain")
+	w.Write(data)
+}

