 	}

 	opts := migrate.Options{}

 	args := os.Args[2:]
 	for i := 0; i < len(args); i++ {
 		switch args[i] {
 		case "--dry-run":
 			opts.DryRun = true
 		case "--config-only":
 			opts.ConfigOnly = true
 		case "--workspace-only":
 			opts.WorkspaceOnly = true
 		case "--force":
 			opts.Force = true
 		case "--refresh":
