+		s.logger.Warn("Inner agent WS: socket not found", zap.String("dveID", dveID), zap.String("socket", socketPath))
+		http.Error(w, fmt.Sprintf(`{"error":"agent not running for dve %s"}`, dveID), http.StatusServiceUnavailable)
+		return
+	}
