+	unixConn, err := net.DialTimeout("unix", socketPath, 5*time.Second)
+	if err != nil {
+		s.logger.Error("Inner agent WS: Unix dial failed", zap.String("dveID", dveID), zap.String("socket", socketPath), zap.Error(err))
